#!/usr/bin/env bash
# Regenerates huff/generated/: the FeeVault creation code the hook's constructor deploys (Solidity's
# `new FeeVault(poolManager)`). CI fails if the committed file is stale.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/.."
code="$(hnc huff/FeeVault.huff -b)"
cat > huff/generated/FeeVaultCreation.huff <<HUFF
/// @dev Generated by script/huff-codegen.sh from huff/FeeVault.huff. Do not edit.
#define table FEE_VAULT_CREATION {
    0x${code}
}
HUFF
